// TH18 v1.00a st04bs::Boss2 (source lines 190-354), ranks 0-3, non-spell.
// Source t0 is Boss2 entry. The independent card restores the upstream representative
// position (0,128); Card1's dynamic handoff is an accepted training difference.
const TIME_LIMIT: int = 2220;      // 120f shell buffer + 2100f local attack estimate
const SOURCE_LIMIT: int = 2100;    // no source timeout: HP-driven non-spell estimate
const OPENING_BUFFER: int = 120;

const TH18_YIN_YANG_R: int = 1056; // source et0 type44
const TH18_YIN_YANG_L: int = 1072; // source et1 type45
const TH18_DROPLET: int = 896;     // source et2 type34
const TH18_BIG_BALL: int = 640;    // source et3 type18

xformdef SPIN(av: angle) {
    // Source at EX: OFFSCREEN(600,b=0), then ANGLE_ACCEL(a=360,r=0.005,s=+/-0.013962634).
    // Birth ANIM/INVULN omitted by policy; the ANIM 4*initial-speed retreat is kept via sh_dist.
    offscreen_keep(600);
    set_ang_vel(av);
    @360 set_accel(0.005fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}
xformdef DELAYED_ACCEL {
    // Source at2 EX: WAIT(120), then VELTIME(a=120,r=3.0,s=current angle).
    // Initial speed is 0.6, so the scalar ramp is (3.0-0.6)/120 = 0.02 per frame.
    wait(120);
    @120 set_accel(0.02fx);
    set_accel(0fx);
}

// moveRand(60,4,0.7) + moveLimit(0,128,280,96), source lines 237/201.
// Actual limits x in [-140,140], y in [80,176]; direction inner zone x +/-70, y 104..152.
// int slot0 = next-step count, fx slots0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx * 0.7fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 412: signed unit random * pi; BAM r is the signed angle.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Source Boss2_at (244-292): et0/et1 fixed rings, counts 5/10/14/17.
sub boss_at_setup() {
    var rank: int = global(GVAR_RANK);
    var n: int = 5;
    if rank == 1 { n = 10; }
    if rank == 2 { n = 14; }
    if rank == 3 { n = 17; }
    sh_reset(0);
    sh_sprite(0, TH18_YIN_YANG_R, 4);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx);
    sh_xform(0, SPIN(0.8deg));
    sh_reset(1);
    sh_sprite(1, TH18_YIN_YANG_L, 3);
    sh_ring(1, 1);
    sh_count(1, n, 1);
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, -6fx);
    sh_xform(1, SPIN(-0.8deg));
}
sub boss_at() {
    sh_fire(0);
    sh_fire(1);
}

// Source Boss2_at2 (294-331): et2 fixed ring, counts 12/24/30/40,
// five RANDRAD fires every 20f then 120f pause, 80 outer rounds.
async sub boss_at2() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    if rank == 1 { n = 24; }
    if rank == 2 { n = 30; }
    if rank == 3 { n = 40; }
    sh_reset(0);
    sh_sprite(0, TH18_DROPLET, 10);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 0.6fx, 0fx);
    sh_dist(0, -2.4fx);
    sh_xform(0, DELAYED_ACCEL);
    for a in 0..80 {
        for b in 0..5 {
            sh_angle(0, (rand(65536)-32768) as angle, 0deg);
            sh_fire(0);
            wait(20);
        }
        wait(120);
    }
}

// Source Boss2_at3 (333-353): one aimed ring bullet while DIST_PLAYER <= 190, every 50f.
async sub boss_at3() {
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL, 5);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 1, 1);
    sh_speed(0, 1.6fx, 0fx);
    sh_dist(0, -6.4fx);
    for i in 0..8000 {
        if dist($player_x-$self_x, $player_y-$self_y) <= 190fx {
            sh_fire(0);
        }
        wait(50);
    }
}

async sub boss_main() {
    // Source Boss2 entry: setInvuln120/lifeSet19400 and cleanup omitted by shell;
    // source hurtbox40/hitbox48 (Boss lines 26-27) map to radii 20/24.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    boss_at_setup();
    wait(90);  // source 226-227
    wait(80);  // source 227-228; EffChargePoint3 is visual only
    set_self_int(2, 60); // source I0 (int slot0/1 are movement scratch)
    set_self_int(3, 1);  // source I1
    spawn boss_at2();
    spawn boss_at3();
    loop {
        boss_at();       // source 235
        card_wait(140);  // source 236
        card_move_rand();// source 237
        card_wait(160);  // source 238
    }
}

async sub encounter() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 19400, 0, 0, 0, boss_main);
    wait(TIME_LIMIT-OPENING_BUFFER);
}
async sub phase_owner() {
    // Training-only phase owner: no source body collision.
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, encounter, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(0); // shell cleanup; phase timeout already cleared bullets
    loop { wait(600); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, phase_owner);
    loop { wait(600); }
}
